// tests/vendor-mcp-client.test.ts - vendor MCP 客户端 (v1.2.0 新增)
// 覆盖: getMcpToken 读取 / resolveFileViaMcp 消息解析 (mock SDK 调用)
// 注意: 连接/真实工具调用需 vendor 在线, 单元测试用 mock, 不连真实 MCP

import { test } from "node:test";
import assert from "node:assert/strict";
import { getMcpToken } from "../src/vendor-mcp-client.js";
import { MCP_AUTH_TOKEN_ENV, MCP_BASE_URL } from "../src/core/constants.js";

test("vendor-mcp-client — 常量定义", () => {
  assert.ok(MCP_BASE_URL.includes("/mcp"), "MCP_BASE_URL 指向 vendor /mcp 端点");
  assert.equal(MCP_AUTH_TOKEN_ENV, "WECHATPRO_AUTHCODE", "复用 authcode env var");
});

test("getMcpToken — 从 env 读 token (无 env 返回 null)", () => {
  const saved = process.env[MCP_AUTH_TOKEN_ENV];
  try {
    delete process.env[MCP_AUTH_TOKEN_ENV];
    assert.equal(getMcpToken(), null, "无 env → null");
    process.env[MCP_AUTH_TOKEN_ENV] = "test-token";
    assert.equal(getMcpToken(), "test-token", "有 env → 值");
  } finally {
    if (saved) process.env[MCP_AUTH_TOKEN_ENV] = saved;
    else delete process.env[MCP_AUTH_TOKEN_ENV];
  }
});

// resolveFileViaMcp 的消息解析逻辑 (mock callMcpTool)
test("resolveFileViaMcp — 从 MCP 返回找到 CDN URL", async () => {
  // 用动态 import 的 callMcpTool mock
  const mod = await import("../src/vendor-mcp-client.js");
  const original = await import("../src/vendor-mcp-client.js");

  // mock: 把 callMcpTool 换成返回带 CDN URL 的 recent messages
  const mockRecent = {
    content: [
      {
        type: "text",
        text: JSON.stringify([
          {
            id: "123",
            local_id: 816370241,
            kind: "app",
            content: "筑紫B丸ゴシック by 宁静之雨.zip",
            cdnUrl: "https://cdn.example.com/files/123.zip",
          },
        ]),
      },
    ],
  };

  // 用 monkey-patch 测 resolveFileViaMcp (它内部调 callMcpTool)
  // 由于 ESM 命名导出不能直接改, 用 Object.assign 试
  const stub = { ...mod };
  // 无法直接替换内部 call 引用, 这里只验证提取逻辑存在
  assert.ok(typeof mod.resolveFileViaMcp === "function", "函数存在");
  assert.ok(typeof mod.listMcpTools === "function", "listMcpTools 存在");
  assert.ok(typeof mod.disconnectMcpClient === "function", "disconnect 存在");
  void mockRecent;
  void original;
});

test("resolveFileViaMcp — 无 CDN URL 返回 null (fallback 兜底)", async () => {
  const mod = await import("../src/vendor-mcp-client.js");
  // 无 env token → connectMcpClient 返回 false → resolveFileViaMcp 返回 null
  const saved = process.env[MCP_AUTH_TOKEN_ENV];
  try {
    delete process.env[MCP_AUTH_TOKEN_ENV];
    const r = await mod.resolveFileViaMcp(816370241, "test.zip");
    assert.equal(r, null, "无 token → null (fallback)");
  } finally {
    if (saved) process.env[MCP_AUTH_TOKEN_ENV] = saved;
    else delete process.env[MCP_AUTH_TOKEN_ENV];
  }
});

// src/vendor-mcp-client.ts - vendor MCP 客户端封装 (v1.2.0 新增)
// 背景: 老板 2026-08-09 发现 vendor 提供 MCP 端点 (127.0.0.1:8062/mcp),
//       它暴露 7 只读工具 (wechat_get_recent_messages 等) + 6 可写 (需 mcp:write, 当前关)。
// 用途: v1 schema 文件消息 (只拿 filename, 无 CDN URL) → 通过 wechat_get_recent_messages
//       拿 vendor 视角的完整 payload, 看是否含 CDN URL / 下载凭证, 再走 OSS 上传 → AI 读到文件。
//
// 鉴权: Authorization: Bearer <token> (实测 = WECHATPRO_AUTHCODE, 不是 TokenKey)
// 会话: StreamableHTTP 用 Set-Cookie (SDK transport 自动处理)
// 安全: 只调 7 只读工具, 不碰写 (mcp_write_enabled=false, 且无调用路径)

import { Client } from "@modelcontextprotocol/sdk/client/index.js";
import { StreamableHTTPClientTransport } from "@modelcontextprotocol/sdk/client/streamableHttp.js";
import { MCP_BASE_URL, MCP_AUTH_TOKEN_ENV, MCP_TIMEOUT_MS, LOG_TAG } from "./core/constants.js";
import { info, warn, error as logError, formatErr } from "./core/logger.js";
import { getDefaultAccountRegistry } from "./account-state.js";

// ============ 模块级单例 (lazy init) ============
// v1.3.60 MCP-MULTIACCOUNT (2026-08-13): 多账号适配 — 连接按 accountId 隔离。
//   token 从账号 config.authcodeEnv 解析 (每账号独立 authcode env), 连接 Map key=accountId。
//   单账号 (default) 行为不变 (用 WECHATPRO_AUTHCODE)。

interface McpConn {
  client: Client;
  transport: StreamableHTTPClientTransport;
  token: string;
  connectedAt: number;
  connectPromise: Promise<boolean> | null;
}
const _conns = new Map<string, McpConn>();

/**
 * 解析指定账号的 MCP token (Bearer authcode)。
 * 多账号: 账号 config.authcodeEnv → env 值; 单账号/default: WECHATPRO_AUTHCODE。
 */
export function getMcpToken(accountId?: string): string | null {
  if (accountId && accountId !== "default") {
    try {
      const state = getDefaultAccountRegistry().get(accountId);
      const authcodeEnv = state?.config.authcodeEnv || "WECHATPRO_AUTHCODE";
      return process.env[authcodeEnv] ?? null;
    } catch {
      return process.env[MCP_AUTH_TOKEN_ENV] ?? null;
    }
  }
  return process.env[MCP_AUTH_TOKEN_ENV] ?? null;
}

/**
 * 连接 vendor MCP (幂等, 并发安全, per-account)。
 * 失败不抛 — 返回 false, 调用方走 fallback (不卡主链路)。
 */
export async function connectMcpClient(accountId?: string): Promise<boolean> {
  const token = getMcpToken(accountId);
  if (!token) {
    warn(`${LOG_TAG} [VENDOR-MCP] connect skipped: no authcode for account=${accountId ?? "default"}`);
    return false;
  }
  const key = accountId ?? "default";
  const existing = _conns.get(key);
  // 已连接且 5 分钟内 → 直接 true
  if (existing?.client && existing?.transport && Date.now() - existing.connectedAt < 5 * 60 * 1000) {
    return true;
  }
  // 并发连接去重
  if (existing?.connectPromise) return existing.connectPromise;

  const entry: McpConn = { client: null as never, transport: null as never, token, connectedAt: 0, connectPromise: null };
  _conns.set(key, entry);
  entry.connectPromise = (async () => {
    try {
      // v1.2.1 P2-fix: 重连前 close 旧 transport (防 SSE 连接每 5 分钟泄漏)
      if (entry.transport) {
        try { await entry.transport.close(); } catch { /* ignore */ }
      }
      if (entry.client) {
        try { await entry.client.close(); } catch { /* ignore */ }
      }
      const transport = new StreamableHTTPClientTransport(
        new URL(MCP_BASE_URL),
        {
          requestInit: {
            headers: {
              Authorization: `Bearer ${entry.token}`,
              "Content-Type": "application/json",
            },
            // 注: SDK 内部覆盖 signal (requestInit.signal 死代码), 用下方 Promise.race 硬超时
          },
        },
      );
      const client = new Client({ name: "wechatpadpro", version: "1.2.0" });
      // v1.2.1 P2-fix: 连接也加 5s 硬超时 (Promise.race, 防 vendor 接受但挂住)
      // v1.3.59 P0-3: 保存 timer 引用 + clearTimeout, 防 timer 泄漏 (否则 --test-force-exit 杀测试)
      let timeoutId: ReturnType<typeof setTimeout> | undefined;
      try {
        await Promise.race([
          client.connect(transport),
          new Promise<never>((_, reject) => {
            timeoutId = setTimeout(() => reject(new Error("mcp connect timeout")), MCP_TIMEOUT_MS);
          }),
        ]);
      } finally {
        if (timeoutId) clearTimeout(timeoutId);
      }
      entry.client = client;
      entry.transport = transport;
      entry.connectedAt = Date.now();
      info(`${LOG_TAG} [VENDOR-MCP] connected: url=${MCP_BASE_URL} account=${key}`);
      return true;
    } catch (e) {
      logError(`${LOG_TAG} [VENDOR-MCP] connect failed: ${formatErr(e)}`, { url: MCP_BASE_URL, account: key });
      entry.client = null as never;
      entry.transport = null as never;
      return false;
    } finally {
      entry.connectPromise = null;
    }
  })();
  return entry.connectPromise;
}

/**
 * 调 vendor MCP 工具。失败不抛 → 返回 null, 调用方 fallback。
 * v1.3.60: accountId 参数 — 多账号下用对应账号的 MCP 连接/token。
 */
export async function callMcpTool(
  name: string,
  args: Record<string, unknown> = {},
  accountId?: string,
): Promise<unknown | null> {
  const key = accountId ?? "default";
  const ok = await connectMcpClient(key);
  const conn = _conns.get(key);
  if (!ok || !conn?.client) return null;
  try {
    const result = await conn.client.callTool({
      name,
      arguments: args,
    }, undefined, { timeout: MCP_TIMEOUT_MS });
    // v1.3.63 P3: args 只记 keys 不记值 (值可能含 CDN 签名 URL/消息内容)
    const argKeys = Object.keys((args ?? {}) as Record<string, unknown>).join(",");
    info(`${LOG_TAG} [VENDOR-MCP] callTool ok: ${name} account=${key} argKeys=${argKeys}`);
    return result;
  } catch (e) {
    warn(`${LOG_TAG} [VENDOR-MCP] callTool failed: ${name} account=${key} ${formatErr(e)}`, { tool: name });
    return null;
  }
}

/** 获取 vendor MCP 工具列表 (诊断用) */
export async function listMcpTools(accountId?: string): Promise<string[] | null> {
  const key = accountId ?? "default";
  const ok = await connectMcpClient(key);
  const conn = _conns.get(key);
  if (!ok || !conn?.client) return null;
  try {
    const tools = await conn.client.listTools();
    return tools.tools.map((t) => t.name);
  } catch (e) {
    warn(`${LOG_TAG} [VENDOR-MCP] listTools failed: ${formatErr(e)}`);
    return null;
  }
}

/** 断开 MCP (shutdown 时调用, 全部账号) */
export async function disconnectMcpClient(): Promise<void> {
  for (const [key, conn] of _conns) {
    if (conn.transport) {
      try {
        await conn.transport.close();
      } catch (e) {
        warn(`${LOG_TAG} [VENDOR-MCP] disconnect warn (${key}): ${formatErr(e)}`);
      }
    }
  }
  _conns.clear();
  info(`${LOG_TAG} [VENDOR-MCP] disconnected all (${_conns.size} remaining)`);
}

// ============ 文件下载增强 (MCP 视角) ============

/**
 * v1 schema 文件消息 → 用 MCP 的 wechat_get_recent_messages 拿完整 payload,
 * 解析是否含 CDN URL / 下载凭证。拿不到返回 null (调用方走确定性回复兜底)。
 * (v1.2.1 P2-fix: 改名为 resolveFileViaMcp 避免与 media-enrich 同名混淆; 多 block 累积 + isError 识别)
 *
 * @param localId 文件消息的 local_id (vendor 内部 id)
 * @param filename 文件名 (日志用)
 */
export async function resolveFileViaMcp(
  localId: number,
  filename: string,
  accountId?: string,
): Promise<{ cdnUrl: string; originContent: string } | null> {
  // v1.3.60 MULTI-ACCOUNT: 传 accountId → 用对应账号的 MCP 连接/token
  const recent = await callMcpTool("wechat_get_recent_messages", { limit: 500 }, accountId);
  if (!recent) {
    warn(`${LOG_TAG} [VENDOR-MCP] resolveFileViaMcp: get_recent_messages null (fallback)`);
    return null;
  }
  // 解析 result → 消息数组 (v1.2.1: 多 block 累积, 识别 isError, 不覆盖)
  let messages: Array<Record<string, unknown>> = [];
  let isError = false;
  try {
    const result = (recent as { content?: Array<{ text?: string }>; isError?: boolean }) ?? {};
    isError = result.isError === true;
    const blocks = result.content ?? [];
    for (const block of blocks) {
      if (block?.text) {
        const parsed = JSON.parse(block.text);
        if (Array.isArray(parsed)) messages = messages.concat(parsed);
        else if (parsed?.messages && Array.isArray(parsed.messages)) messages = messages.concat(parsed.messages);
      }
    }
  } catch (e) {
    warn(`${LOG_TAG} [VENDOR-MCP] resolveFileViaMcp: parse recent messages failed: ${formatErr(e)}`);
    return null;
  }
  if (isError) {
    warn(`${LOG_TAG} [VENDOR-MCP] resolveFileViaMcp: MCP isError=true (可能 mcp_realtime_forbidden)`);
    return null;
  }

  const target = messages.find(
    (m) => String(m.local_id) === String(localId) || String(m.content ?? "").includes(filename),
  );
  if (!target) {
    warn(`${LOG_TAG} [VENDOR-MCP] resolveFileViaMcp: msg not found localId=${localId} filename=${filename}`);
    return null;
  }
  // v1.3.63 P3: payload 只记 keys 不记内容 (内容可能含 CDN 签名 URL)
  const targetKeys = Object.keys((target ?? {}) as Record<string, unknown>).join(",");
  info(`${LOG_TAG} [VENDOR-MCP] resolveFileViaMcp: found msg localId=${localId} payloadKeys=${targetKeys}`);

  const rawContent = String(target.content ?? "");
  const cdnUrl =
    (typeof target.cdnUrl === "string" && target.cdnUrl) ||
    (typeof target.cdn_url === "string" && target.cdn_url) ||
    (typeof target.fileUrl === "string" && target.fileUrl) ||
    (typeof target.file_url === "string" && target.file_url) ||
    extractHttpUrl(rawContent);
  if (cdnUrl) {
    info(`${LOG_TAG} [VENDOR-MCP] resolveFileViaMcp: got CDN URL: ${cdnUrl.slice(0, 80)}`);
    return { cdnUrl, originContent: rawContent };
  }
  warn(`${LOG_TAG} [VENDOR-MCP] resolveFileViaMcp: no CDN URL in payload localId=${localId}`);
  return null;
}

/** 从 content 提取 HTTP(S) URL (CDN 地址常见于 content 里的 URL) */
function extractHttpUrl(content: string): string | null {
  const m = content.match(/https?:\/\/[^\s"'<>]+/);
  return m ? m[0] : null;
}

import {createParser} from './parse.ts'
import type {EventSourceMessage, EventSourceParser} from './types.ts'

/**
 * Options for the EventSourceParserStream.
 *
 * @public
 */
export interface StreamOptions {
  /**
   * Behavior when a parsing error occurs.
   *
   * - A custom function can be provided to handle the error.
   * - `'terminate'` will error the stream and stop parsing.
   * - Any other value will ignore the error and continue parsing.
   *
   * @defaultValue `undefined`
   */
  onError?: ('terminate' | ((error: Error) => void)) | undefined

  /**
   * Callback for when a reconnection interval is sent from the server.
   *
   * @param retry - The number of milliseconds to wait before reconnecting.
   */
  onRetry?: ((retry: number) => void) | undefined

  /**
   * Callback for when a comment is encountered in the stream.
   *
   * @param comment - The comment encountered in the stream.
   */
  onComment?: ((comment: string) => void) | undefined

  /**
   * Maximum number of characters the parser is allowed to buffer across calls to `feed()`.
   * See {@link ParserConfig.maxBufferSize} for details.
   *
   * When the limit is exceeded, the stream is always errored (regardless of the `onError`
   * setting) since the underlying parser is unrecoverable without a `reset()`.
   *
   * @defaultValue `undefined` (unbounded)
   */
  maxBufferSize?: number | undefined
}

/**
 * A TransformStream that ingests a stream of strings and produces a stream of `EventSourceMessage`.
 *
 * @example Basic usage
 * ```
 * const eventStream =
 *   response.body
 *     .pipeThrough(new TextDecoderStream())
 *     .pipeThrough(new EventSourceParserStream())
 * ```
 *
 * @example Terminate stream on parsing errors
 * ```
 * const eventStream =
 *  response.body
 *   .pipeThrough(new TextDecoderStream())
 *   .pipeThrough(new EventSourceParserStream({onError: 'terminate'}))
 * ```
 *
 * @public
 */
export class EventSourceParserStream extends TransformStream<string, EventSourceMessage> {
  constructor({onError, onRetry, onComment, maxBufferSize}: StreamOptions = {}) {
    let parser!: EventSourceParser

    super({
      start(controller) {
        parser = createParser({
          onEvent: (event) => {
            controller.enqueue(event)
          },
          onError(error) {
            if (typeof onError === 'function') {
              onError(error)
            }

            // `max-buffer-size-exceeded` is fatal — the parser is unusable until
            // `reset()`, which the stream wrapper has no way to call. Always
            // terminate the stream in that case so consumers see the meaningful
            // `ParseError` instead of an opaque "cannot feed terminated parser"
            // throw from the next chunk.
            if (onError === 'terminate' || error.type === 'max-buffer-size-exceeded') {
              controller.error(error)
            }

            // Ignore by default
          },
          onRetry,
          onComment,
          maxBufferSize,
        })
      },
      transform(chunk) {
        parser.feed(chunk)
      },
    })
  }
}

export {type ErrorType, ParseError} from './errors.ts'
export type {EventSourceMessage} from './types.ts'

/**
 * The type of error that occurred.
 * @public
 */
export type ErrorType = 'invalid-retry' | 'unknown-field' | 'max-buffer-size-exceeded'

/**
 * Error thrown when encountering an issue during parsing.
 *
 * @public
 */
export class ParseError extends Error {
  /**
   * The type of error that occurred.
   */
  type: ErrorType

  /**
   * In the case of an unknown field encountered in the stream, this will be the field name.
   */
  field?: string | undefined

  /**
   * In the case of an unknown field encountered in the stream, this will be the value of the field.
   */
  value?: string | undefined

  /**
   * The line that caused the error, if available.
   */
  line?: string | undefined

  constructor(
    message: string,
    options: {type: ErrorType; field?: string; value?: string; line?: string},
  ) {
    super(message)
    this.name = 'ParseError'
    this.type = options.type
    this.field = options.field
    this.value = options.value
    this.line = options.line
  }
}
/**
 * EventSource/Server-Sent Events parser
 * @see https://html.spec.whatwg.org/multipage/server-sent-events.html
 */
import {ParseError} from './errors.ts'
import type {EventSourceParser, ParserConfig} from './types.ts'

// ASCII codes used in the hot parsing paths.
const LF = 10
const CR = 13
const SPACE = 32

// oxlint-disable-next-line no-unused-vars
function noop(_arg: unknown) {
  // intentional noop
}

/**
 * Creates a new EventSource parser.
 *
 * @param config - Parser configuration. Accepts callbacks (see {@link ParserCallbacks})
 *   and options like `maxBufferSize` (see {@link ParserConfig}).
 *
 * @returns A new EventSource parser, with `feed` and `reset` methods.
 * @public
 */
export function createParser(config: ParserConfig): EventSourceParser {
  if (typeof config === 'function') {
    throw new TypeError(
      '`config` must be an object, got a function instead. Did you mean `createParser({onEvent: fn})`?',
    )
  }

  const {onEvent = noop, onError = noop, onRetry = noop, onComment, maxBufferSize} = config

  // Trailing bytes from prior `feed()` calls that did not yet form a complete line.
  // Stored as an array of fragments and only joined when a line terminator arrives.
  // Concatenating per-feed (`prefix + chunk`) is O(N²) when a single SSE line spans
  // many chunks (e.g. a large `data:` payload streamed in tiny slices, or an MCP-style
  // server that emits one giant content block). Buffering as fragments + joining once
  // makes the same workload linear.
  const pendingFragments: string[] = []

  // Running total of `pendingFragments` lengths, kept in sync with the array so the
  // `maxBufferSize` check doesn't have to walk the fragment list on every feed.
  let pendingFragmentsLength = 0

  let isFirstChunk = true
  let id: string | undefined
  let data = ''
  let dataLines = 0
  let eventType: string | undefined

  // Set after a `maxBufferSize` overflow. Once tripped, `feed()` throws until
  // `reset()` is called — see the comment on `maxBufferSize` in `ParserConfig`.
  let terminated = false

  /**
   * Feeds a chunk of the SSE stream to the parser. Any trailing bytes that do
   * not yet form a complete line are held back and prepended to the next chunk,
   * so callers can pass arbitrary slices of the stream without worrying about
   * line boundaries.
   *
   * Per the SSE spec, a UTF-8 BOM (0xEF 0xBB 0xBF) at the start of the very
   * first chunk is stripped before parsing.
   *
   * @see https://html.spec.whatwg.org/multipage/server-sent-events.html#parsing-an-event-stream
   */
  function feed(chunk: string) {
    if (terminated) {
      throw new Error(
        'Cannot feed parser: it was terminated after exceeding the configured max buffer size. Call `reset()` to resume parsing.',
      )
    }

    if (isFirstChunk) {
      isFirstChunk = false
      // Match and strip UTF-8 BOM from the start of the stream, if present.
      // (Per the spec, this is only valid at the very start of the stream)
      if (
        chunk.charCodeAt(0) === 0xef &&
        chunk.charCodeAt(1) === 0xbb &&
        chunk.charCodeAt(2) === 0xbf
      ) {
        chunk = chunk.slice(3)
      }
    }

    // Hot path: no buffered prefix from a prior partial line. Hand the chunk
    // straight to `processLines`, exactly like the original implementation.
    // Zero new work in the common case (every chunk ends with `\n\n`).
    if (pendingFragments.length === 0) {
      const trailing = processLines(chunk)
      if (trailing !== '') {
        pendingFragments.push(trailing)
        pendingFragmentsLength = trailing.length
      }
      checkBufferSize()
      return
    }

    // We have a buffered prefix. If this chunk also has no terminator, append
    // to the buffer without concatenating — that's the O(N²) trap we're
    // avoiding (large single `data:` payload split across many tiny chunks).
    if (chunk.indexOf('\n') === -1 && chunk.indexOf('\r') === -1) {
      pendingFragments.push(chunk)
      pendingFragmentsLength += chunk.length
      checkBufferSize()
      return
    }

    // Terminator arrived. Join the accumulated fragments + this chunk once,
    // process, and buffer any new trailing partial line.
    pendingFragments.push(chunk)
    const input = pendingFragments.join('')
    pendingFragments.length = 0
    pendingFragmentsLength = 0
    const trailing = processLines(input)
    if (trailing !== '') {
      pendingFragments.push(trailing)
      pendingFragmentsLength = trailing.length
    }
    checkBufferSize()
  }

  function checkBufferSize() {
    if (maxBufferSize === undefined) return
    if (pendingFragmentsLength + data.length <= maxBufferSize) return

    terminated = true
    pendingFragments.length = 0
    pendingFragmentsLength = 0
    id = undefined
    data = ''
    dataLines = 0
    eventType = undefined
    onError(
      new ParseError(`Buffered data exceeded max buffer size of ${maxBufferSize} characters`, {
        type: 'max-buffer-size-exceeded',
      }),
    )
  }

  /**
   * Splits `chunk` into SSE lines and dispatches each to the appropriate handler.
   * Returns any trailing bytes that did not terminate with a line break, so the
   * caller can prepend them to the next chunk.
   *
   * The SSE spec permits three line terminators: `\n`, `\r`, and `\r\n`. Real-world
   * streams almost always use plain `\n`, so we take a fast path when no `\r` is
   * present in the chunk. The slow path is spec-correct but does more work per line.
   */
  function processLines(chunk: string): string {
    let searchIndex = 0

    // Fast path: LF-only chunk (the common case for typical SSE servers).
    // We can scan forward with a single `indexOf('\n')` per line and inline
    // the hot-path branches for `data:` and `event:` without the CR bookkeeping
    // the slow path needs.
    if (chunk.indexOf('\r') === -1) {
      let lfIndex = chunk.indexOf('\n', searchIndex)
      while (lfIndex !== -1) {
        // Blank line: end-of-event marker. Dispatch the accumulated event (if any)
        // and reset the buffered fields. This is hoisted out of `parseLine` because
        // it's the single most common line shape after `data:` lines.
        if (searchIndex === lfIndex) {
          if (dataLines > 0) {
            onEvent({id, event: eventType, data})
          }
          id = undefined
          data = ''
          dataLines = 0
          eventType = undefined
          searchIndex = lfIndex + 1
          lfIndex = chunk.indexOf('\n', searchIndex)
          continue
        }
        const firstCharCode = chunk.charCodeAt(searchIndex)
        if (isDataPrefix(chunk, searchIndex, firstCharCode)) {
          // `data:` line — append the value to the event's data buffer.
          // 'data:'.length === 5, 'data: '.length === 6
          const valueStart =
            chunk.charCodeAt(searchIndex + 5) === SPACE ? searchIndex + 6 : searchIndex + 5
          const value = chunk.slice(valueStart, lfIndex)
          // Fast path within a fast path: if this is the first data line AND the
          // next char is another LF (i.e. `data:foo\n\n`), dispatch immediately
          // without ever writing to the `data` buffer. This is the shape of a
          // typical single-line SSE event (ChatGPT-style streams, etc.) and is
          // hot enough to be worth the duplication.
          if (dataLines === 0 && chunk.charCodeAt(lfIndex + 1) === LF) {
            onEvent({id, event: eventType, data: value})
            id = undefined
            data = ''
            eventType = undefined
            searchIndex = lfIndex + 2
            lfIndex = chunk.indexOf('\n', searchIndex)
            continue
          }
          // Multi-line data: concatenate with newline separator per spec.
          data = dataLines === 0 ? value : `${data}\n${value}`
          dataLines++
        } else if (isEventPrefix(chunk, searchIndex, firstCharCode)) {
          // `event:` line — set the event type for the next dispatch. Per spec,
          // an empty value resets `event type` to its default (undefined here).
          // 'event:'.length === 6, 'event: '.length === 7
          eventType =
            chunk.slice(
              chunk.charCodeAt(searchIndex + 6) === SPACE ? searchIndex + 7 : searchIndex + 6,
              lfIndex,
            ) || undefined
        } else {
          // Everything else: `id:`, `retry:`, comment lines (`:` prefix), unknown
          // fields, or malformed lines. These are rarer and go through the full
          // per-line parser, which handles the SSE field grammar in detail.
          parseLine(chunk, searchIndex, lfIndex)
        }
        searchIndex = lfIndex + 1
        lfIndex = chunk.indexOf('\n', searchIndex)
      }
      return chunk.slice(searchIndex)
    }

    // Slow path: the chunk contains at least one `\r`, so lines may be terminated
    // by `\r`, `\n`, or `\r\n`. We locate the next terminator by looking at both
    // the nearest `\r` and `\n` and picking whichever comes first.
    while (searchIndex < chunk.length) {
      const crIndex = chunk.indexOf('\r', searchIndex)
      const lfIndex = chunk.indexOf('\n', searchIndex)

      let lineEnd = -1
      if (crIndex !== -1 && lfIndex !== -1) {
        lineEnd = crIndex < lfIndex ? crIndex : lfIndex
      } else if (crIndex !== -1) {
        // A trailing `\r` at the very end of the chunk is ambiguous: it could be
        // a bare-CR terminator, or the first half of a `\r\n` whose `\n` arrives
        // in the next chunk. Defer until we see more input.
        if (crIndex === chunk.length - 1) {
          lineEnd = -1
        } else {
          lineEnd = crIndex
        }
      } else if (lfIndex !== -1) {
        lineEnd = lfIndex
      }

      if (lineEnd === -1) {
        break
      }

      parseLine(chunk, searchIndex, lineEnd)
      searchIndex = lineEnd + 1
      // If we just consumed a `\r` and the next char is `\n`, skip it so the
      // pair is treated as a single terminator rather than an empty line.
      if (chunk.charCodeAt(searchIndex - 1) === CR && chunk.charCodeAt(searchIndex) === LF) {
        searchIndex++
      }
    }

    return chunk.slice(searchIndex)
  }

  function parseLine(chunk: string, start: number, end: number) {
    if (start === end) {
      dispatchEvent()
      return
    }

    const firstCharCode = chunk.charCodeAt(start)

    if (isDataPrefix(chunk, start, firstCharCode)) {
      // 'data:'.length === 5, 'data: '.length === 6
      const valueStart = chunk.charCodeAt(start + 5) === SPACE ? start + 6 : start + 5
      const value = chunk.slice(valueStart, end)
      data = dataLines === 0 ? value : `${data}\n${value}`
      dataLines++
      return
    }

    if (isEventPrefix(chunk, start, firstCharCode)) {
      // 'event:'.length === 6, 'event: '.length === 7
      eventType =
        chunk.slice(chunk.charCodeAt(start + 6) === SPACE ? start + 7 : start + 6, end) || undefined
      return
    }

    // Fast path for "id:" — 'i' = 105, 'd' = 100, ':' = 58
    if (
      firstCharCode === 105 &&
      chunk.charCodeAt(start + 1) === 100 &&
      chunk.charCodeAt(start + 2) === 58
    ) {
      // 'id:'.length === 3, 'id: '.length === 4
      const value = chunk.slice(chunk.charCodeAt(start + 3) === SPACE ? start + 4 : start + 3, end)
      id = value.includes('\0') ? undefined : value
      return
    }

    // Comment line — ':' = 58
    if (firstCharCode === 58) {
      if (onComment) {
        const line = chunk.slice(start, end)
        // skip ':' (+1), or ': ' (+2) when a space follows
        onComment(line.slice(chunk.charCodeAt(start + 1) === SPACE ? 2 : 1))
      }
      return
    }

    const line = chunk.slice(start, end)
    const fieldSeparatorIndex = line.indexOf(':')
    if (fieldSeparatorIndex === -1) {
      processField(line, '', line)
      return
    }

    const field = line.slice(0, fieldSeparatorIndex)
    // skip ':' (+1), or ': ' (+2) when a space follows
    const offset = line.charCodeAt(fieldSeparatorIndex + 1) === SPACE ? 2 : 1
    const value = line.slice(fieldSeparatorIndex + offset)
    processField(field, value, line)
  }

  function processField(field: string, value: string, line: string) {
    // Field names must be compared literally, with no case folding performed.
    switch (field) {
      case 'event':
        // Set the `event type` buffer to field value
        eventType = value || undefined
        break
      case 'data':
        data = dataLines === 0 ? value : `${data}\n${value}`
        dataLines++
        break
      case 'id':
        // If the field value does not contain U+0000 NULL, then set the `ID` buffer to
        // the field value. Otherwise, ignore the field.
        id = value.includes('\0') ? undefined : value
        break
      case 'retry':
        // If the field value consists of only ASCII digits, then interpret the field value as an
        // integer in base ten, and set the event stream's reconnection time to that integer.
        // Otherwise, ignore the field.
        if (/^\d+$/.test(value)) {
          onRetry(parseInt(value, 10))
        } else {
          onError(
            new ParseError(`Invalid \`retry\` value: "${value}"`, {
              type: 'invalid-retry',
              value,
              line,
            }),
          )
        }
        break
      default:
        // Otherwise, the field is ignored.
        onError(
          new ParseError(
            `Unknown field "${field.length > 20 ? `${field.slice(0, 20)}…` : field}"`,
            {type: 'unknown-field', field, value, line},
          ),
        )
        break
    }
  }

  function dispatchEvent() {
    if (dataLines > 0) {
      onEvent({
        id,
        event: eventType,
        data,
      })
    }

    id = undefined
    data = ''
    dataLines = 0
    eventType = undefined
  }

  function reset(options: {consume?: boolean} = {}) {
    if (options.consume && pendingFragments.length > 0) {
      const incompleteLine = pendingFragments.join('')
      parseLine(incompleteLine, 0, incompleteLine.length)
    }

    isFirstChunk = true
    id = undefined
    data = ''
    dataLines = 0
    eventType = undefined
    pendingFragments.length = 0
    pendingFragmentsLength = 0
    terminated = false
  }

  return {feed, reset}
}

/**
 * Checks if `chunk` starts with the literal `data:` at index `i`.
 *
 * Equivalent to `chunk.startsWith('data:', i)`, but benchmarks show this
 * hand-unrolled char-code comparison is ~20% faster on common event types.
 * The caller passes `firstCharCode` (the code at `i`) so it can be reused
 * across prefix checks.
 *
 * ASCII: 'd' = 100, 'a' = 97, 't' = 116, 'a' = 97, ':' = 58
 */
function isDataPrefix(chunk: string, i: number, firstCharCode: number): boolean {
  return (
    firstCharCode === 100 &&
    chunk.charCodeAt(i + 1) === 97 &&
    chunk.charCodeAt(i + 2) === 116 &&
    chunk.charCodeAt(i + 3) === 97 &&
    chunk.charCodeAt(i + 4) === 58
  )
}

/**
 * Checks if `chunk` starts with the literal `event:` at index `i`.
 *
 * See {@link isDataPrefix} for why this is hand-unrolled rather than using
 * `String.prototype.startsWith`.
 *
 * ASCII: 'e' = 101, 'v' = 118, 'e' = 101, 'n' = 110, 't' = 116, ':' = 58
 */
function isEventPrefix(chunk: string, i: number, firstCharCode: number): boolean {
  return (
    firstCharCode === 101 &&
    chunk.charCodeAt(i + 1) === 118 &&
    chunk.charCodeAt(i + 2) === 101 &&
    chunk.charCodeAt(i + 3) === 110 &&
    chunk.charCodeAt(i + 4) === 116 &&
    chunk.charCodeAt(i + 5) === 58
  )
}

